    /// Needs <c>code:update</c>. Without <c>remoteUrl</c> the project is disconnected. Give a credential the caller may use (<c>code.git.credentials.list</c>): <c>credentialId</c> for a token, <c>connectionId</c> for a signed-in GitHub account.
    /// <para/>
    /// <c>PUT /api/code/projects/{projectId}/git</c>
    /// </remarks>
    /// <param name="projectId">The code project's id.</param>
    /// <param name="body">The body.</param>
    /// <param name="options">Per-call timeout, retries and headers.</param>
    /// <param name="cancellationToken">Cancels the call.</param>
    /// <returns>The answer.</returns>
    /// <exception cref="CrafvyException">The API refused the call.</exception>
    public Task<CodeGitConnectResponse?> ConnectAsync(string projectId, CodeGitConnectBody body, RequestOptions? options = null, CancellationToken cancellationToken = default)
        => _requester.CallAsync<CodeGitConnectResponse?>("PUT", "/api/code/projects/" + Requester.Seg(projectId) + "/git", null, body, false, null, options, cancellationToken);

    /// <summary>Lists the commits of a code project's branch, its branches, one commit's changes, or one file as last synced.</summary>
    /// <remarks>
    /// One of: nothing — the branch's latest 30 commits (<c>commits</c>); <c>branches=1</c> — the repository's branches; <c>sha</c> — that commit's <c>message</c> and <c>files</c> with their diffs; <c>path</c> — that file's <c>content</c> at the commit the project last synced to (null when there is none).
    /// <para/>
    /// <c>GET /api/code/projects/{projectId}/git/history</c>
    /// </remarks>
    /// <param name="projectId">The code project's id.</param>
    /// <param name="query">The query (may be null).</param>
    /// <param name="options">Per-call timeout, retries and headers.</param>
    /// <param name="cancellationToken">Cancels the call.</param>
    /// <returns>The answer.</returns>
    /// <exception cref="CrafvyException">The API refused the call.</exception>
    public Task<CodeGitHistoryResponse?> HistoryAsync(string projectId, CodeGitHistoryQuery? query = null, RequestOptions? options = null, CancellationToken cancellationToken = default)
        => _requester.CallAsync<CodeGitHistoryResponse?>("GET", "/api/code/projects/" + Requester.Seg(projectId) + "/git/history", query, null, false, null, options, cancellationToken);

    /// <summary>Lists the repositories a git credential can push to, or one repository's branches.</summary>
    /// <remarks>
    /// Give <c>credentialId</c> or <c>connectionId</c> (with its <c>workspaceId</c>). With <c>repo</c>, the answer is that repository's <c>branches</c> instead of <c>repos</c>.
    /// <para/>
    /// <c>GET /api/code/git/repos</c>
    /// </remarks>
    /// <param name="query">The query (may be null).</param>
    /// <param name="options">Per-call timeout, retries and headers.</param>
    /// <param name="cancellationToken">Cancels the call.</param>
    /// <returns>The answer.</returns>
    /// <exception cref="CrafvyException">The API refused the call.</exception>
    public Task<CodeGitReposResponse?> ReposAsync(CodeGitReposQuery? query = null, RequestOptions? options = null, CancellationToken cancellationToken = default)
        => _requester.CallAsync<CodeGitReposResponse?>("GET", "/api/code/git/repos", query, null, false, null, options, cancellationToken);

    /// <summary>Returns a code project's repository connection and what differs from it.</summary>
    /// <remarks>
    /// Needs Git sync on the account. <c>connected: false</c> with a <c>reason</c> when there is no repository or no usable credential.
    /// <para/>
    /// <c>GET /api/code/projects/{projectId}/git</c>
    /// </remarks>
    /// <param name="projectId">The code project's id.</param>
    /// <param name="options">Per-call timeout, retries and headers.</param>
    /// <param name="cancellationToken">Cancels the call.</param>
    /// <returns>The answer.</returns>
    /// <exception cref="CrafvyException">The API refused the call.</exception>
    public Task<CodeGitStatusResponse?> StatusAsync(string projectId, RequestOptions? options = null, CancellationToken cancellationToken = default)
        => _requester.CallAsync<CodeGitStatusResponse?>("GET", "/api/code/projects/" + Requester.Seg(projectId) + "/git", null, null, false, null, options, cancellationToken);

    /// <summary>Pulls from, pushes to, or switches the branch of a code project's repository.</summary>
    /// <remarks>
    /// Needs <c>code:update</c>. <c>pull</c> refuses to overwrite local changes unless <c>force</c>; <c>push</c> makes one commit of what changed and refuses when the branch moved since the last sync; <c>switch-branch</c> refuses with local changes (409) unless <c>force</c>, which discards them.
    /// <para/>
    /// <c>POST /api/code/projects/{projectId}/git</c>
    /// </remarks>
    /// <param name="projectId">The code project's id.</param>
    /// <param name="body">The body.</param>
    /// <param name="options">Per-call timeout, retries and headers.</param>
    /// <param name="cancellationToken">Cancels the call.</param>
    /// <returns>The answer.</returns>
    /// <exception cref="CrafvyException">The API refused the call.</exception>
    public Task<CodeGitSyncResponse?> SyncAsync(string projectId, CodeGitSyncBody body, RequestOptions? options = null, CancellationToken cancellationToken = default)
        => _requester.CallAsync<CodeGitSyncResponse?>("POST", "/api/code/projects/" + Requester.Seg(projectId) + "/git", null, body, false, null, options, cancellationToken);
}

/// <summary><c>code.git.credentials</c></summary>
public sealed class CodeGitCredentialsResource
{
    private readonly Requester _requester;

    internal CodeGitCredentialsResource(Requester requester)
    {
        _requester = requester;
    }

    /// <summary>Stores a git host access token, after the host accepted it.</summary>
    /// <remarks>
    /// Needs <c>code:update</c>; a credential shared with an organization (<c>scope: organization</c>) also needs <c>organization:update</c>. The token is stored encrypted and never comes back.
    /// <para/>
    /// <c>POST /api/code/git/credentials</c>
    /// </remarks>
    /// <param name="body">The body.</param>
    /// <param name="options">Per-call timeout, retries and headers.</param>
    /// <param name="cancellationToken">Cancels the call.</param>
    /// <returns>The answer's <c>credential</c>.</returns>
    /// <exception cref="CrafvyException">The API refused the call.</exception>
    public Task<CodeGitCredential?> CreateAsync(CodeGitCredentialsCreateBody body, RequestOptions? options = null, CancellationToken cancellationToken = default)
        => _requester.CallAsync<CodeGitCredential?>("POST", "/api/code/git/credentials", null, body, false, "credential", options, cancellationToken);

    /// <summary>Deletes a git credential or a signed-in GitHub account.</summary>
    /// <remarks><c>DELETE /api/code/git/credentials</c></remarks>
    /// <param name="query">The query.</param>
    /// <param name="options">Per-call timeout, retries and headers.</param>
    /// <param name="cancellationToken">Cancels the call.</param>
    /// <returns>The answer.</returns>
    /// <exception cref="CrafvyException">The API refused the call.</exception>
    public Task<CodeGitCredentialsDeleteResponse?> DeleteAsync(CodeGitCredentialsDeleteQuery query, RequestOptions? options = null, CancellationToken cancellationToken = default)
        => _requester.CallAsync<CodeGitCredentialsDeleteResponse?>("DELETE", "/api/code/git/credentials", query, null, false, null, options, cancellationToken);

    /// <summary>Lists the git credentials the caller may use, without their tokens.</summary>
    /// <remarks>
    /// The caller's own tokens and their organizations' shared ones; with <c>workspaceId</c>, also the GitHub accounts signed in to in that workspace.
    /// <para/>
    /// <c>GET /api/code/git/credentials</c>
    /// </remarks>
    /// <param name="query">The query (may be null).</param>
    /// <param name="options">Per-call timeout, retries and headers.</param>
    /// <param name="cancellationToken">Cancels the call.</param>
    /// <returns>The answer's <c>credentials</c>.</returns>
    /// <exception cref="CrafvyException">The API refused the call.</exception>
    public Task<List<CodeGitCredential>?> ListAsync(CodeGitCredentialsListQuery? query = null, RequestOptions? options = null, CancellationToken cancellationToken = default)
        => _requester.CallAsync<List<CodeGitCredential>?>("GET", "/api/code/git/credentials", query, null, false, "credentials", options, cancellationToken);
}

/// <summary><c>code.projects</c></summary>
public sealed class CodeProjectsResource
{
    private readonly Requester _requester;

    internal CodeProjectsResource(Requester requester)
    {
        _requester = requester;
    }

    /// <summary>Creates a code project, from a template or with a starter file.</summary>
    /// <remarks>
    /// Needs <c>code:create</c> and the Coding hub on the plan; counts against the organization's <c>max_code_projects</c>. Without <c>template</c> the project starts with the language's starter file, unless <c>empty</c> is true.
    /// <para/>
    /// <c>POST /api/code/projects</c>
    /// </remarks>
    /// <param name="body">The body.</param>
    /// <param name="options">Per-call timeout, retries and headers.</param>
    /// <param name="cancellationToken">Cancels the call.</param>
    /// <returns>The answer's <c>project</c>.</returns>
    /// <exception cref="CrafvyException">The API refused the call.</exception>
    public Task<CodeProject?> CreateAsync(CodeProjectsCreateBody body, RequestOptions? options = null, CancellationToken cancellationToken = default)
        => _requester.CallAsync<CodeProject?>("POST", "/api/code/projects", null, body, false, "project", options, cancellationToken);

    /// <summary>Moves a code project to the trash.</summary>
    /// <remarks>
    /// Needs <c>code:delete</c>, and only the owner may. What runs stops and its sites go offline; the files wait in the trash until it is deleted for good.
    /// <para/>
    /// <c>DELETE /api/code/projects/{projectId}</c>
    /// </remarks>
    /// <param name="projectId">The code project's id.</param>
    /// <param name="options">Per-call timeout, retries and headers.</param>
    /// <param name="cancellationToken">Cancels the call.</param>
    /// <returns>The answer.</returns>
    /// <exception cref="CrafvyException">The API refused the call.</exception>
    public Task<CodeProjectsDeleteResponse?> DeleteAsync(string projectId, RequestOptions? options = null, CancellationToken cancellationToken = default)
        => _requester.CallAsync<CodeProjectsDeleteResponse?>("DELETE", "/api/code/projects/" + Requester.Seg(projectId), null, null, false, null, options, cancellationToken);

    /// <summary>Downloads a code project's files as a ZIP file.</summary>
    /// <remarks>
    /// Answers the file itself (<c>application/zip</c>), not JSON. Uploaded files live in the Assets hub and are only listed, in <c>UPLOADS.txt</c>.
    /// <para/>
    /// <c>GET /api/code/projects/{projectId}/download</c>
    /// </remarks>
    /// <param name="projectId">The code project's id.</param>
    /// <param name="options">Per-call timeout, retries and headers.</param>
    /// <param name="cancellationToken">Cancels the call.</param>
    /// <returns>The answer.</returns>
    /// <exception cref="CrafvyException">The API refused the call.</exception>
    public Task<object?> DownloadAsync(string projectId, RequestOptions? options = null, CancellationToken cancellationToken = default)
        => _requester.CallAsync<object?>("GET", "/api/code/projects/" + Requester.Seg(projectId) + "/download", null, null, false, null, options, cancellationToken);

    /// <summary>Returns a code project with its file tree, without the files' contents.</summary>
    /// <remarks>
    /// Read a file's content with <c>code.files.get</c>.
    /// <para/>
    /// <c>GET /api/code/projects/{projectId}</c>
    /// </remarks>
    /// <param name="projectId">The code project's id.</param>
    /// <param name="options">Per-call timeout, retries and headers.</param>
    /// <param name="cancellationToken">Cancels the call.</param>
    /// <returns>The answer.</returns>
    /// <exception cref="CrafvyException">The API refused the call.</exception>
    public Task<CodeProjectsGetResponse?> GetAsync(string projectId, RequestOptions? options = null, CancellationToken cancellationToken = default)
        => _requester.CallAsync<CodeProjectsGetResponse?>("GET", "/api/code/projects/" + Requester.Seg(projectId), null, null, false, null, options, cancellationToken);

    /// <summary>Lists the caller's code projects, and the shared ones of a workspace or organization.</summary>
    /// <remarks>
    /// Always the caller's own. With <c>workspaceId</c>, also that workspace's projects shared with it; with <c>organizationId</c>, also the organization's projects shared with it — each only where the caller belongs. Most recently opened first; projects in the trash are left out.
    /// <para/>
    /// <c>GET /api/code/projects</c>
    /// </remarks>
    /// <param name="query">The query (may be null).</param>
    /// <param name="options">Per-call timeout, retries and headers.</param>
    /// <param name="cancellationToken">Cancels the call.</param>
    /// <returns>The answer's <c>projects</c>.</returns>
    /// <exception cref="CrafvyException">The API refused the call.</exception>
    public Task<List<CodeProjectsListResponseProjectsItem>?> ListAsync(CodeProjectsListQuery? query = null, RequestOptions? options = null, CancellationToken cancellationToken = default)
        => _requester.CallAsync<List<CodeProjectsListResponseProjectsItem>?>("GET", "/api/code/projects", query, null, false, "projects", options, cancellationToken);

    /// <summary>Renames, describes, archives or re-scopes a code project.</summary>
    /// <remarks>
    /// Needs <c>code:update</c>. Only the owner may change <c>visibility</c>; people who lose write access are disconnected from live editing at once.
    /// <para/>
    /// <c>PATCH /api/code/projects/{projectId}</c>
    /// </remarks>
    /// <param name="projectId">The code project's id.</param>
    /// <param name="body">The body.</param>
    /// <param name="options">Per-call timeout, retries and headers.</param>
    /// <param name="cancellationToken">Cancels the call.</param>
    /// <returns>The answer's <c>project</c>.</returns>
    /// <exception cref="CrafvyException">The API refused the call.</exception>
    public Task<CodeProject?> UpdateAsync(string projectId, CodeProjectsUpdateBody body, RequestOptions? options = null, CancellationToken cancellationToken = default)
        => _requester.CallAsync<CodeProject?>("PATCH", "/api/code/projects/" + Requester.Seg(projectId), null, body, false, "project", options, cancellationToken);
}
